INSERT INTO knowledge_cards
       (user_id, source_text, source_url, source_title, source_meta, catalog_title,
        ai_summary, ai_subjects, ai_keywords, ai_facts, ai_related,
        ai_catalog_status, ai_embedding_status,
        visibility, published_at, share_source_text, created_at, updated_at)
SELECT u.id, '', s.source_url, s.source_title, s.source_meta, s.catalog_title,
       s.summary, s.subjects, s.keywords, s.facts, s.related,
       'NOT_AVAILABLE', 'NOT_AVAILABLE',
       'PUBLIC', now() - make_interval(hours => s.hours_ago), false,
       now() - make_interval(hours => s.hours_ago + 24), now() - make_interval(hours => s.hours_ago)
  FROM seed_cards s
  JOIN users u ON u.email = s.owner_email
 WHERE NOT EXISTS (
       SELECT 1 FROM knowledge_cards k
         JOIN users o ON o.id = k.user_id
        WHERE k.source_url = s.source_url
          AND o.email LIKE '%@seed.cardvault.test')
 ORDER BY s.n;

